// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.List;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Differential tests for DISTINCT + ORDER BY + LIMIT when the sort key is not projected (gap-analysis B1). SPARQL
 * semantics dedup the <em>sorted</em> projected sequence: for each projected key the surviving representative is its
 * best-sorted row, so which keys make the LIMIT depends on each key's best sort value. Deduplicating in producer
 * encounter order before sorting keeps an arbitrary representative per key and can push the wrong keys out of the top
 * slice. When every sort key is itself projected the pre-sort dedup is safe — duplicates then share identical sort keys
 * — which the control test pins.
 */
public class LmdbNativeDistinctOrderLimitTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String JANINO_FLAG = "rdf4j.lmdb.janinoCodegen.enabled";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private String previousJanino;

	@BeforeEach
	public void setUp() {
		// Pin the codegen tier off so the top-K sort tier under test is the one that actually runs.
		previousJanino = System.getProperty(JANINO_FLAG);
		System.setProperty(JANINO_FLAG, "false");
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI name = vf.createIRI(EX, "name");
			IRI age = vf.createIRI(EX, "age");
			// The "shared" name's worst-aged row is inserted first so producer encounter order meets it before
			// the best-aged row — the exact trap for encounter-order dedup.
			IRI p1 = vf.createIRI(EX, "p1");
			IRI p2 = vf.createIRI(EX, "p2");
			IRI p3 = vf.createIRI(EX, "p3");
			conn.add(p1, name, vf.createLiteral("shared"));
			conn.add(p1, age, vf.createLiteral(90));
			conn.add(p2, name, vf.createLiteral("shared"));
			conn.add(p2, age, vf.createLiteral(5));
			conn.add(p3, name, vf.createLiteral("other"));
			conn.add(p3, age, vf.createLiteral(50));
		}
	}

	@AfterEach
	public void tearDown() {
		if (previousJanino == null) {
			System.clearProperty(JANINO_FLAG);
		} else {
			System.setProperty(JANINO_FLAG, previousJanino);
		}
		if (repository != null) {
			repository.shutDown();
		}
	}

	/**
	 * Ages sorted: (shared,5), (other,50), (shared,90). The sorted-dedup keeps "shared" via its age-5 row, so LIMIT 1
	 * must return "shared". Encounter-order dedup meets (shared,90) first, keeps that representative, and the top-1 by
	 * age then wrongly selects "other".
	 */
	@Test
	public void unprojectedSortKeyKeepsBestSortedRepresentativePerKey() {
		String query = "SELECT DISTINCT ?name WHERE { ?p <http://example.com/name> ?name ."
				+ " ?p <http://example.com/age> ?age } ORDER BY ?age LIMIT 1";

		List<String> generic = genericRows(query);
		assertThat(generic)
				.as("interpreted engine: dedup runs over the sorted sequence, so 'shared' survives via age 5")
				.containsExactly("name=\"shared\"");
		assertThat(rows(query))
				.as("native rows must match the interpreted engine when the sort key is unprojected")
				.isEqualTo(generic);
	}

	/** The full slice: membership and order must both follow each key's best-sorted row. */
	@Test
	public void unprojectedSortKeyOrdersKeysByTheirBestRow() {
		String query = "SELECT DISTINCT ?name WHERE { ?p <http://example.com/name> ?name ."
				+ " ?p <http://example.com/age> ?age } ORDER BY ?age LIMIT 2";

		List<String> generic = genericRows(query);
		assertThat(generic)
				.as("interpreted engine: shared (age 5) precedes other (age 50)")
				.containsExactly("name=\"shared\"", "name=\"other\"");
		assertThat(rows(query))
				.as("native rows must match the interpreted engine when the sort key is unprojected")
				.isEqualTo(generic);
	}

	/** Control: with the sort key projected, duplicates share sort keys and the pre-sort dedup stays safe. */
	@Test
	public void projectedSortKeyKeepsTopKDedupSafe() {
		String query = "SELECT DISTINCT ?name WHERE { ?p <http://example.com/name> ?name ."
				+ " ?p <http://example.com/age> ?age } ORDER BY ?name LIMIT 2";

		List<String> generic = genericRows(query);
		assertThat(generic).containsExactly("name=\"other\"", "name=\"shared\"");
		assertThat(rows(query))
				.as("native rows must match the interpreted engine when the sort key is projected")
				.isEqualTo(generic);
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(LmdbNativeDistinctOrderLimitTest::render)
					.collect(Collectors.toList());
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String render(BindingSet bindings) {
		return bindings.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + bindings.getValue(name))
				.collect(Collectors.joining("|"));
	}
}
